-- ==============================================================================
-- EXAMSARTHI — Seed Data
-- ==============================================================================
-- Populates Master Question Bank (36 questions), Competitive Mock Exams (e1..e3),
-- and Subject Practice Sets (p1..p5) with deterministic cohort mappings.
-- ==============================================================================

-- 1. SEED EXAMS & PRACTICE SETS
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  subject = EXCLUDED.subject,
  description = EXCLUDED.description,
  duration_minutes = EXCLUDED.duration_minutes,
  difficulty = EXCLUDED.difficulty,
  total_questions = EXCLUDED.total_questions,
  is_active = EXCLUDED.is_active;

-- 2. SEED MASTER QUESTION BANK (36 Questions across 5 Formats)
ON CONFLICT (id) DO UPDATE SET
  type = EXCLUDED.type,
  text = EXCLUDED.text,
  subject = EXCLUDED.subject,
  topic = EXCLUDED.topic,
  difficulty = EXCLUDED.difficulty,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  acceptable_answers = EXCLUDED.acceptable_answers,
  explanation = EXCLUDED.explanation;

-- 3. SEED EXAM_QUESTIONS MAPPINGS
ON CONFLICT (exam_id, question_id) DO UPDATE SET
  section_name = EXCLUDED.section_name,
  order_index = EXCLUDED.order_index;
